/* AULA360 — Motores del catálogo de Física (modelos propios con las leyes físicas reales; sin dependencias externas).
   Motor principal: «banco» = banco de experimentos parametrizado (controles → modelo físico → instrumentos con resolución y ruido
   → tabla → gráfica y ajuste → tareas verificables → retos). Cada laboratorio declara sus límites. */
window.FMOT=(function(){
const E={};
const esc=s=>String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fm=(v,d)=>isFinite(v)?(+v).toFixed(d==null?2:d).replace('.',','):'—';
const $=(el,s)=>el.querySelector(s);
const btn=(id,t,c)=>`<button id="${id}" class="sim-btn" style="background:${c||'#4f46e5'}">${t}</button>`;
const lab=t=>`<label style="display:block;font-size:12px;font-weight:800;margin-top:8px">${t}</label>`;
const rnd=s=>{let a=s>>>0||1;return()=>{a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296}};
const gauss=r=>{let u=0,v=0;while(!u)u=r();while(!v)v=r();return Math.sqrt(-2*Math.log(u))*Math.cos(2*Math.PI*v)};
const quant=(x,res)=>res?Math.round(x/res)*res:x;
const dec=res=>res>=1?0:Math.min(4,Math.max(0,Math.ceil(-Math.log10(res)-1e-9)));
const panel=(t,h)=>`<div class="sim-panel"><div class="sim-h">${t}</div>${h}</div>`;
/* ---------- retos de opción múltiple ---------- */
const mkRetos=(el,RT,ctx,P)=>{const S={k:0,ok:0};
 const draw=()=>{const d=$(el,'#'+P+'_rt'),r=RT[S.k];if(!d)return;if(!RT.length){d.style.display='none';return}
  if(!r){d.innerHTML='🏁 <b>¡Retos completados!</b> '+S.ok+' de '+RT.length;return}
  d.innerHTML=`<b>Reto ${S.k+1}/${RT.length}:</b> ${esc(r.q)}<div style="display:flex;flex-wrap:wrap;gap:6px;margin-top:6px">${r.o.map((o,i)=>`<button data-o="${i}" class="sim-btn" style="background:#7c3aed">${esc(o)}</button>`).join('')}</div>`;
  d.querySelectorAll('[data-o]').forEach(b=>b.onclick=()=>{const ok=+b.dataset.o===r.ok,f=$(el,'#'+P+'_fb');if(ok){S.ok++;ctx.act('reto_ok',{});f.style.color='#16a34a'}else f.style.color='#dc2626';f.textContent=(ok?'✅ ':'❌ ')+(r.why||'');
   ctx.obs('Reto '+(S.k+1)+': '+(ok?'acierto':'error'));S.k++;if(S.k>=RT.length&&S.ok>=Math.ceil(RT.length*0.7))ctx.act('todo_ok',{});draw()})};
 return{draw,reset(){S.k=0;S.ok=0;const f=$(el,'#'+P+'_fb');if(f)f.textContent='';draw()}}};
/* ---------- ajuste lineal ---------- */
const fit=(xs,ys,origen)=>{const n=xs.length;if(n<2)return null;
 if(origen){let sxy=0,sxx=0;xs.forEach((x,i)=>{sxy+=x*ys[i];sxx+=x*x});return sxx?{m:sxy/sxx,b:0}:null}
 const mx=xs.reduce((a,b)=>a+b,0)/n,my=ys.reduce((a,b)=>a+b,0)/n;let sxy=0,sxx=0;xs.forEach((x,i)=>{sxy+=(x-mx)*(ys[i]-my);sxx+=(x-mx)*(x-mx)});if(!sxx)return null;const m=sxy/sxx;return{m,b:my-m*mx}};
/* ---------- dibujos (canvas 2D) ---------- */
const D={};
const line=(g,x1,y1,x2,y2,c,w)=>{g.strokeStyle=c||'#334155';g.lineWidth=w||1;g.beginPath();g.moveTo(x1,y1);g.lineTo(x2,y2);g.stroke()};
const txt=(g,t,x,y,c,s,al)=>{g.fillStyle=c||'#0f172a';g.font=(s||12)+'px sans-serif';g.textAlign=al||'left';g.fillText(t,x,y)};
const rect=(g,x,y,w,h,f,s)=>{if(f){g.fillStyle=f;g.fillRect(x,y,w,h)}if(s){g.strokeStyle=s;g.strokeRect(x,y,w,h)}};
const circ=(g,x,y,r,f,s)=>{g.beginPath();g.arc(x,y,r,0,7);if(f){g.fillStyle=f;g.fill()}if(s){g.strokeStyle=s;g.stroke()}};
D.barras=(g,W,H,v,o,S)=>{const ks=(S.cfg.outs||[]).filter(k=>isFinite(o[k.id]));const w=Math.min(60,(W-40)/Math.max(1,ks.length)-10);ks.forEach((k,i)=>{const mx=k.max||Math.max(1,Math.abs(o[k.id])*1.5),h=Math.max(2,Math.min(1,Math.abs(o[k.id])/mx)*(H-60)),x=30+i*(w+10);rect(g,x,H-30-h,w,h,'#818cf8');txt(g,fm(o[k.id],2),x+w/2,H-34-h,'#1e1b4b',11,'center');txt(g,k.n.slice(0,12),x+w/2,H-12,'#475569',10,'center')})};
D.regla=(g,W,H,v,o)=>{const L=o.L,vm=o._vmax||25,x0=30,sc=(W-60)/vm;rect(g,x0,70,vm*sc,34,'#fde68a','#92400e');for(let i=0;i<=vm*10;i++){const x=x0+i*sc/10,h=i%10===0?16:i%5===0?11:6;line(g,x,70,x,70+h,'#78350f',1);if(i%10===0&&(vm<=30||i%50===0))txt(g,String(i/10),x,126,'#78350f',10,'center')}
 rect(g,x0+(o._x0||0)*sc,28,L*sc,32,o._c||'#60a5fa','#1e3a8a');txt(g,o._n||'Objeto',x0+(o._x0||0)*sc+L*sc/2,48,'#fff',11,'center');
 if(o._cal){rect(g,x0+(o._x0||0)*sc,140,L*sc,10,'#94a3b8');rect(g,x0+(o._x0||0)*sc+L*sc,140,10,26,'#64748b');txt(g,'calibrador',x0,175,'#64748b',11)}};
D.probeta=(g,W,H,v,o)=>{const cx=W/2-70,top=20,hh=H-50,w=50,V0=o._V0,V2=o._V2,cap=o._cap||100;[[cx,V0,'Antes'],[cx+150,V2,'Después']].forEach(([x,V,t])=>{rect(g,x,top,w,hh,null,'#334155');const h=V/cap*hh;rect(g,x+1,top+hh-h,w-2,h,'#7dd3fc');for(let i=0;i<=10;i++){const y=top+hh-i*hh/10;line(g,x,y,x+(i%5===0?14:8),y,'#334155');if(i%2===0)txt(g,String(i*cap/10),x-6,y+4,'#334155',10,'right')}txt(g,t,x+w/2,H-8,'#475569',11,'center')});
 circ(g,cx+175,top+hh-14,10,o._c||'#78716c','#1f2937');txt(g,o._n||'Cuerpo',cx+175,top-4,'#475569',11,'center')};
D.balanza=(g,W,H,v,o)=>{rect(g,W/2-90,H-60,180,40,'#cbd5e1','#64748b');rect(g,W/2-60,H-80,120,16,'#94a3b8');rect(g,W/2-55,H-130,110,32,'#0f172a');txt(g,fm(o.m,1)+' g',W/2,H-107,'#4ade80',20,'center');const s=o._side||40;rect(g,W/2-s/2,H-80-s,s,s,o._c||'#a16207','#451a03');txt(g,o._n||'',W/2,H-85-s,'#475569',11,'center')};
D.torre=(g,W,H,v,o)=>{const ls=o._layers||[],x=W/2-45,top=20,hh=H-50;rect(g,x,top,90,hh,null,'#334155');let y=top+hh;const tot=ls.reduce((a,l)=>a+l.V,0),sc=Math.min(hh/Math.max(tot,1),hh/60);ls.forEach(l=>{const h=l.V*sc;y-=h;rect(g,x+1,y,88,h,l.c);txt(g,l.n+' ('+fm(l.rho,2)+' g/mL)',x+100,y+h/2+4,'#334155',11)});if(!ls.length)txt(g,'Agrega líquidos',W/2,H/2,'#64748b',13,'center')};
D.curva=(g,W,H,v,o,S)=>{const x0=46,y0=H-34,w=W-70,h=H-60,tm=S.cfg.tmax||30,Tm=S.cfg.Tmax||130,Tn=S.cfg.Tmin||-20;line(g,x0,y0,x0+w,y0);line(g,x0,y0,x0,y0-h);const X=t=>x0+t/tm*w,Y=T=>y0-(T-Tn)/(Tm-Tn)*h;
 g.strokeStyle='#cbd5e1';g.beginPath();for(let t=0;t<=tm;t+=.25){const T=S.cfg.curvaT(t,v);t?g.lineTo(X(t),Y(T)):g.moveTo(X(t),Y(T))}g.stroke();
 g.strokeStyle='#4f46e5';g.lineWidth=2;g.beginPath();for(let t=0;t<=v.t+1e-9;t+=.25){const T=S.cfg.curvaT(t,v);t?g.lineTo(X(t),Y(T)):g.moveTo(X(t),Y(T))}g.stroke();g.lineWidth=1;circ(g,X(v.t),Y(o.T),5,'#ef4444');txt(g,'t (min)',x0+w,y0+14,'#475569',10,'right');txt(g,'T (°C)',x0+4,12,'#475569',10);txt(g,o._fase||'',x0+w/2,16,'#0f172a',12,'center')};
D.anillo=(g,W,H,v,o)=>{const cx=W/2,cy=H/2,r=o.D/20*55,rr=o._ring/20*55;circ(g,cx,cy,rr+8,null,'#475569');circ(g,cx,cy,rr,'#f8fafc','#475569');g.lineWidth=1;circ(g,cx,cy,r,o.pasa?'#34d399':'#f87171','#1f2937');txt(g,o.pasa?'La esfera PASA por el anillo':'La esfera NO pasa',cx,H-14,o.pasa?'#047857':'#b91c1c',13,'center');txt(g,'T = '+fm(v.T,0)+' °C',cx,18,'#334155',12,'center')};
D.varillas=(g,W,H,v,o,S)=>{(S.cfg.varillas||[]).forEach((r,i)=>{const y=24+i*42,L=o[r.id],sc=(W-120)/6;rect(g,60,y,6*sc,16,'#cbd5e1','#64748b');rect(g,60,y,Math.min(6,L)*sc,16,r.c);txt(g,r.n,6,y+13,'#334155',11);txt(g,fm(L,1)+' cm',W-52,y+13,'#334155',11)})};
D.termo=(g,W,H,v,o)=>{const x=W/2-10,top=14,hh=H-70;rect(g,x,top,20,hh,'#f1f5f9','#334155');circ(g,x+10,top+hh+16,18,'#ef4444','#334155');const h=Math.min(hh,Math.max(2,o._frac*hh));rect(g,x+6,top+hh-h,8,h+4,'#ef4444');for(let i=0;i<=10;i++)line(g,x+20,top+hh-i*hh/10,x+28,top+hh-i*hh/10,'#334155');txt(g,'columna: '+fm(o.h,1)+' mm',x+40,top+hh/2,'#334155',13)};
D.carga=(g,W,H,v,o)=>{const cx=W/2;circ(g,cx-80,H/2,46,o.q<0?'#93c5fd':'#fca5a5','#1e3a8a');txt(g,o.q<0?'−':'+',cx-80,H/2+8,'#111',26,'center');txt(g,'globo',cx-80,H/2+66,'#475569',11,'center');const n=Math.min(12,Math.round(Math.abs(o.F)*4));for(let i=0;i<12;i++){const y=H-24-(i<n?Math.min(70,Math.abs(o.F)*8):0);rect(g,cx+20+i*14,y,8,4,'#fde047','#a16207')}txt(g,'papelitos atraídos: '+n,cx+90,24,'#334155',12,'center')};
D.electroscopio=(g,W,H,v,o)=>{const cx=W/2,cy=H/2+10;rect(g,cx-50,cy-30,100,100,'#e0f2fe','#334155');line(g,cx,cy-60,cx,cy-10,'#334155',3);circ(g,cx,cy-66,8,'#94a3b8','#334155');const a=(o.th||0)*Math.PI/180;line(g,cx,cy-10,cx-Math.sin(a)*50,cy-10+Math.cos(a)*50,'#facc15',4);line(g,cx,cy-10,cx+Math.sin(a)*50,cy-10+Math.cos(a)*50,'#facc15',4);txt(g,'θ = '+fm(o.th,0)+'°',cx,H-8,'#334155',13,'center')};
D.iman=(g,W,H,v,o)=>{const cy=H/2;rect(g,30,cy-18,70,36,'#ef4444');rect(g,100,cy-18,70,36,'#2563eb');txt(g,'N',65,cy+6,'#fff',16,'center');txt(g,'S',135,cy+6,'#fff',16,'center');const x=170+v.d*((W-260)/15);rect(g,x,cy-14,28,28,o._c||'#94a3b8','#334155');txt(g,o._n||'',x+14,cy+34,'#334155',10,'center');txt(g,'d = '+fm(v.d,1)+' cm',W/2,16,'#334155',12,'center');if(Math.abs(o.F)>0.01)txt(g,(o.F>0?'atracción ':'repulsión ')+fm(Math.abs(o.F),1)+' mN',W/2,H-10,'#0f172a',13,'center')};
D.campo=(g,W,H,v,o)=>{const cx=W/2,cy=H/2;rect(g,cx-50,cy-14,50,28,'#ef4444');rect(g,cx,cy-14,50,28,'#2563eb');for(let k=1;k<=4;k++){g.strokeStyle='rgba(99,102,241,'+(0.9-k*0.15)+')';g.beginPath();g.ellipse(cx,cy,60+k*30,18+k*16,0,0,7);g.stroke()}const x=cx+50+v.r*((W/2-70)/16);circ(g,x,cy,9,'#f8fafc','#334155');line(g,x-8,cy,x+8,cy,'#ef4444',3);txt(g,'r = '+fm(v.r,1)+' cm · B = '+fm(o.B,2)+' mT',W/2,H-10,'#0f172a',12,'center')};
D.brujula=(g,W,H,v,o)=>{const cx=W/2,cy=H/2+6;circ(g,cx,cy,72,'#f8fafc','#334155');txt(g,'N',cx,cy-56,'#dc2626',14,'center');txt(g,'S',cx,cy+66,'#334155',14,'center');const a=(o.err||0)*Math.PI/180;line(g,cx-Math.sin(a)*-50,cy-Math.cos(a)*50,cx+Math.sin(a)*-50,cy+Math.cos(a)*50,'#334155',1);line(g,cx,cy,cx+Math.sin(a)*54,cy-Math.cos(a)*54,'#ef4444',5);line(g,cx,cy,cx-Math.sin(a)*54,cy+Math.cos(a)*54,'#2563eb',5);txt(g,'desviación del norte: '+fm(Math.abs(o.err),0)+'°',cx,H-8,'#0f172a',12,'center')};
D.convec=(g,W,H,v,o)=>{const x=W/2-90;rect(g,x,40,180,H-80,'#e0f2fe','#334155');rect(g,x,40,90,H-80,'rgba(239,68,68,.35)');rect(g,x+90,40,90,H-80,'rgba(59,130,246,.35)');const n=Math.max(1,Math.min(7,Math.round(o.u*3)));for(let i=0;i<n;i++){const y=60+i*((H-140)/n);line(g,x+45,H-60-i*8,x+45,60+i*8,'#b91c1c',2);line(g,x+135,60+i*8,x+135,H-60-i*8,'#1d4ed8',2)}txt(g,'caliente',x+45,H-46,'#b91c1c',12,'center');txt(g,'fría',x+135,H-46,'#1d4ed8',12,'center');txt(g,'ΔT = '+fm(v.dT,0)+' °C',W/2,24,'#334155',12,'center')};

/* ---- dibujos de séptimo ---- */
D.resorte=(g,W,H,v,o)=>{const x=W/2-40,top=16,len=o._len;rect(g,x-30,top-8,100,8,'#64748b');g.strokeStyle='#334155';g.lineWidth=2;g.beginPath();g.moveTo(x+20,top);const n=14,hh=(len)/n;for(let i=0;i<n;i++){g.lineTo(x+(i%2?36:4),top+hh*(i+.5));}g.lineTo(x+20,top+len);g.stroke();g.lineWidth=1;const mh=10+o._m/12;rect(g,x+20-18,top+len,36,mh,'#6366f1','#1e1b4b');txt(g,fm(o._m,0)+' g',x+20,top+len+mh/2+4,'#fff',11,'center');line(g,x+80,top,x+80,H-16,'#94a3b8');for(let i=0;i<=10;i++){const y=top+i*(H-32)/10;line(g,x+80,y,x+88,y,'#94a3b8');if(i%2===0)txt(g,String(i*(o._rulemax||25)/10),x+92,y+4,'#64748b',10)}line(g,x+60,top+len+mh,x+90,top+len+mh,'#ef4444',1);txt(g,'x = '+fm(o.x,1)+' cm',x+130,top+len+mh,'#b91c1c',12)};
D.fuerzas=(g,W,H,v,o)=>{const cx=W/2,cy=H/2,sc=Math.min(W,H)/14;circ(g,cx,cy,7,'#fff','#334155');[['F1',v.F1,v.a1,'#2563eb'],['F2',v.F2,v.a2,'#16a34a'],['F3',v.F3,v.a3,'#ea580c']].forEach(([n,F,a,c])=>{const r=a*Math.PI/180,x=cx+Math.cos(r)*F*sc,y=cy-Math.sin(r)*F*sc;line(g,cx,cy,x,y,c,3);circ(g,x,y,4,c);txt(g,n+'='+fm(F,1)+' N',x+(x>cx?6:-6),y-6,c,11,x>cx?'left':'right')});const Rr=o.R;txt(g,Rr<0.15?'Anillo en EQUILIBRIO':'Resultante: '+fm(Rr,2)+' N',cx,H-10,Rr<0.15?'#047857':'#b91c1c',13,'center')};
D.bloque=(g,W,H,v,o)=>{const y=H-70;rect(g,20,y,W-40,16,o._c||'#a8a29e','#44403c');const s=40+v.m*14,x=W/2-s/2+(o.a>0?Math.min(60,o.a*8):0);rect(g,x,y-s,s,s,'#fbbf24','#78350f');txt(g,v.m+' kg',x+s/2,y-s/2+4,'#451a03',12,'center');line(g,x+s,y-s/2,x+s+Math.min(90,v.F*6),y-s/2,'#2563eb',3);txt(g,'F = '+fm(v.F,1)+' N',x+s+4,y-s/2-8,'#2563eb',11);line(g,x,y-4,x-Math.min(90,o.f*6),y-4,'#dc2626',3);txt(g,'f = '+fm(o.f,2)+' N',x-4,y-12,'#dc2626',11,'right');txt(g,o.a>0?'EN MOVIMIENTO  a = '+fm(o.a,2)+' m/s²':'En reposo (rozamiento estático)',W/2,24,'#0f172a',13,'center')};
D.cartulina=(g,W,H,v,o)=>{const sc=(H-40)/10,x0=60,y0=H-20;const P=[[1,1],[8.6,0.6],[9.2,5.5],[6,8.4],[2.4,9.2],[0.6,5]];g.fillStyle='#fde68a';g.strokeStyle='#92400e';g.beginPath();P.forEach((p,i)=>{const X=x0+p[0]*sc*1.2,Y=y0-p[1]*sc;i?g.lineTo(X,Y):g.moveTo(X,Y)});g.closePath();g.fill();g.stroke();const px=x0+v.x*sc*1.2,py=y0-v.y*sc;circ(g,px,py,5,'#ef4444');const t=(o.th||0)*Math.PI/180;line(g,px,py,px+Math.sin(t)*70,py+Math.cos(t)*70,'#334155',1);txt(g,'punto de apoyo ('+fm(v.x,1)+'; '+fm(v.y,1)+')',px+8,py-8,'#b91c1c',11);txt(g,'inclinación: '+fm(o.th,1)+'°'+(o.th<=1?'  ✔ EQUILIBRIO':''),W-14,20,o.th<=1?'#047857':'#334155',13,'right')};
D.torrebloq=(g,W,H,v,o)=>{const base=H-40,bw=+v.b*5,bh=26,ang=v.ang*Math.PI/180;g.save();g.translate(W/2,base);g.rotate(-ang);rect(g,-120,0,240,10,'#94a3b8','#475569');for(let i=0;i<v.n;i++)rect(g,-bw/2,-(i+1)*bh,bw,bh,o.cae?'#fca5a5':'#a5b4fc','#312e81');g.restore();txt(g,o.cae?'⚠ LA TORRE CAE':'La torre se mantiene',W/2,22,o.cae?'#b91c1c':'#047857',14,'center');txt(g,'Inclinación '+v.ang+'° · base '+v.b+' cm · '+v.n+' bloques',W/2,H-8,'#475569',11,'center')};
D.palanca=(g,W,H,v,o)=>{const cx=W/2,cy=H/2+30,a=(o.th||0)*Math.PI/180,sc=(W/2-30)/50;g.save();g.translate(cx,cy);g.rotate(-a);rect(g,-50*sc,-6,100*sc,12,'#d6b370','#78350f');for(let i=-5;i<=5;i++){line(g,i*10*sc,-6,i*10*sc,-12,'#78350f',1);txt(g,String(Math.abs(i)*10),i*10*sc,-16,'#78350f',9,'center')}rect(g,-v.d1*sc-14,6,28,18+v.m1/25,'#6366f1','#1e1b4b');txt(g,v.m1+' g',-v.d1*sc,22+v.m1/50,'#fff',10,'center');rect(g,v.d2*sc-14,6,28,18+v.m2/25,'#f97316','#7c2d12');txt(g,v.m2+' g',v.d2*sc,22+v.m2/50,'#fff',10,'center');g.restore();g.fillStyle='#64748b';g.beginPath();g.moveTo(cx-18,cy+40);g.lineTo(cx+18,cy+40);g.lineTo(cx,cy);g.fill();txt(g,Math.abs(o.th)<0.4?'EQUILIBRIO':'Inclinación '+fm(o.th,1)+'°',cx,22,Math.abs(o.th)<0.4?'#047857':'#b91c1c',14,'center')};
D.poleas=(g,W,H,v,o)=>{const cx=W/2;rect(g,cx-80,10,160,8,'#64748b');const n=o.n;circ(g,cx-30,52,16,'#e2e8f0','#334155');if(n>=2)circ(g,cx+20,130,16,'#e2e8f0','#334155');if(n>=4)circ(g,cx+20,95,12,'#e2e8f0','#334155');line(g,cx-46,52,cx-46,200,'#334155',2);line(g,cx-14,52,cx-14,120,'#334155',2);rect(g,cx-30,190,60,34,'#6366f1','#1e1b4b');txt(g,fm(v.kg,0)+' kg',cx,212,'#fff',12,'center');txt(g,'Ventaja mecánica = '+n+'  ·  F = '+fm(o.F,1)+' N',W/2,H-8,'#0f172a',13,'center');line(g,cx-14,120,cx-14,150,'#dc2626',3);txt(g,'F',cx-10,160,'#dc2626',12)};
D.plano=(g,W,H,v,o)=>{const a=v.ang*Math.PI/180,x0=40,y0=H-30,L=W-110,xe=x0+L*Math.cos(a),ye=y0-L*Math.sin(a);g.fillStyle='#d6d3d1';g.beginPath();g.moveTo(x0,y0);g.lineTo(xe,y0);g.lineTo(xe,ye);g.closePath();g.fill();g.strokeStyle='#44403c';g.stroke();g.save();g.translate(x0+L*0.55*Math.cos(a),y0-L*0.55*Math.sin(a));g.rotate(-a);rect(g,-22,-30,44,30,'#6366f1','#1e1b4b');txt(g,v.m+' kg',0,-10,'#fff',11,'center');line(g,22,-15,22+o.F*4,-15,'#dc2626',3);g.restore();txt(g,'θ = '+v.ang+'°',x0+50,y0-8,'#334155',12);txt(g,'F para subir = '+fm(o.F,2)+' N  (peso = '+fm(v.m*9.8,1)+' N)',W/2,18,'#0f172a',12,'center')};
D.presion=(g,W,H,v,o)=>{const w=Math.sqrt(+v.A)*6,hh=50;rect(g,40,H-70,W-80,60,'#fbcfe8','#9d174d');const sink=Math.min(40,o.hund*3);rect(g,W/2-w/2,H-70-hh+sink,w,hh,'#6366f1','#1e1b4b');txt(g,v.m+' kg',W/2,H-70-hh/2+sink+4,'#fff',11,'center');txt(g,'área de apoyo: '+v.A+' cm²',W/2,24,'#334155',12,'center');txt(g,'hundimiento: '+fm(o.hund,1)+' mm',W/2,H-10,'#9d174d',12,'center')};
D.botella=(g,W,H,v,o)=>{const x=60,w=70,top=20,hh=H-70,sc=hh/42,Hn=v.H;rect(g,x,top,w,hh,null,'#334155');rect(g,x+1,top+hh-Hn*sc,w-2,Hn*sc,'rgba(56,189,248,.5)');const yh=top+hh-v.y*sc;circ(g,x+w,yh,3,'#ef4444');const R=o.xr;g.strokeStyle='#0ea5e9';g.lineWidth=2;g.beginPath();g.moveTo(x+w,yh);for(let t=0;t<=1;t+=.05){const X=x+w+R*t*2.2,Y=yh+Math.pow(t,2)*(top+hh-yh);g.lineTo(X,Y)}g.stroke();g.lineWidth=1;line(g,20,top+hh,W-20,top+hh,'#78350f',3);txt(g,'profundidad = '+fm(o.h,0)+' cm · alcance = '+fm(R,1)+' cm',W-20,20,'#0f172a',12,'right')};
D.tubou=(g,W,H,v,o)=>{const x=W/2,base=H-30,sc=(H-70)/32;rect(g,x-90,20,50,H-50,null,'#334155');rect(g,x+40,20,50,H-50,null,'#334155');rect(g,x-90,base-0,180,0,null,null);rect(g,x-89,base-v.hw*sc,48,v.hw*sc,'rgba(56,189,248,.55)');rect(g,x+41,base-o.h2*sc,48,o.h2*sc,o._c||'rgba(250,204,21,.6)');line(g,x-110,base-v.hw*sc,x+110,base-v.hw*sc,'#94a3b8');txt(g,'agua '+fm(v.hw,1)+' cm',x-65,base-v.hw*sc-6,'#0369a1',11,'center');txt(g,o._n+' '+fm(o.h2,1)+' cm',x+65,base-o.h2*sc-6,'#78350f',11,'center')};
D.prensa=(g,W,H,v,o)=>{const cx=W/2,s1=+v.D1*14,s2=+v.D2*14;rect(g,cx-120,H-60,240,40,'rgba(56,189,248,.5)','#334155');rect(g,cx-100-s1/2,H-110,s1,50,'#94a3b8','#334155');rect(g,cx+60-s2/2,H-110,s2,50,'#94a3b8','#334155');line(g,cx-100,H-110-Math.min(60,v.F1),cx-100,H-110,'#dc2626',3);txt(g,'F₁='+fm(v.F1,0)+' N',cx-100,H-120-Math.min(60,v.F1),'#dc2626',11,'center');rect(g,cx+60-40,H-150,80,40,'#6366f1','#1e1b4b');txt(g,'F₂='+fm(o.F2,0)+' N',cx+60,H-125,'#fff',11,'center');txt(g,'Relación de áreas = '+fm((v.D2/v.D1)**2,1),W/2,20,'#0f172a',13,'center')};
D.dinamo=(g,W,H,v,o)=>{const x=W/2-30;rect(g,x-20,14,40,60,'#e2e8f0','#334155');txt(g,fm(o.Wap,2)+' N',x,50,'#0f172a',13,'center');line(g,x,74,x,110,'#334155',2);const top=110;rect(g,x-60,top+10,120,H-top-30,'rgba(56,189,248,.35)','#334155');const vs=v.Vs/50,oy=top+10+vs*(H-top-60);rect(g,x-16,oy-4,32,36,o._c||'#94a3b8','#334155');line(g,x,110,x,oy-4,'#334155',2);txt(g,o._n||'',x+70,top+30,'#64748b',11,'left');txt(g,'empuje = '+fm(o.E,3)+' N',W-14,20,'#0369a1',12,'right')};
D.tension=(g,W,H,v,o)=>{const y=H/2;rect(g,30,y,W-60,H/2-20,'rgba(56,189,248,.35)');line(g,30,y,W-30,y,'#0284c7',2);const s=Math.max(0,o.marg)>0?0:12+(-o.marg)*8;g.strokeStyle='#334155';g.lineWidth=3;g.beginPath();g.moveTo(W/2-60,y-s-3);g.lineTo(W/2+60,y-s-3);g.stroke();g.lineWidth=1;txt(g,o.marg>=0?'La aguja FLOTA (tensión superficial sostiene '+fm(o.fmax,2)+' mN)':'La aguja SE HUNDE (peso '+fm(o.peso,2)+' mN > '+fm(o.fmax,2)+' mN)',W/2,26,o.marg>=0?'#047857':'#b91c1c',12,'center')};
D.capilar=(g,W,H,v,o)=>{const base=H-30,sc=(H-80)/60;rect(g,30,base-70,W-60,70,'rgba(56,189,248,.35)','#334155');[0,1,2].forEach(i=>{const d=[+v.d,+v.d*1.5,+v.d*2.2][i],hh=o.h*(+v.d)/d;const w=Math.max(4,d*7),x=W/2-130+i*130;rect(g,x-w/2,base-70-hh*sc,w,hh*sc+70,'rgba(56,189,248,.8)','#334155');txt(g,'d='+fm(d,2)+' mm',x,base+14,'#475569',10,'center');txt(g,fm(hh,1)+' mm',x,base-76-hh*sc,'#0369a1',10,'center')});txt(g,v.liq+' · ascenso (tubo 1) = '+fm(o.h,1)+' mm',W/2,18,'#0f172a',12,'center')};

/* ---- dibujos de octavo ---- */
D.escalas=(g,W,H,v,o)=>{const T=o.C,top=24,hh=H-70,fr=(T+40)/150;[[W/2-110,'°C',T,'#ef4444',-40,110,10],[W/2+50,'°F',o.F,'#2563eb',-40,230,30]].forEach(([x,u,val,c,a,b,st])=>{rect(g,x,top,22,hh,'#f1f5f9','#334155');circ(g,x+11,top+hh+14,16,c,'#334155');rect(g,x+7,top+hh-fr*hh,8,fr*hh+4,c);for(let k=a;k<=b;k+=st){const y=top+hh-(k-a)/(b-a)*hh;line(g,x+22,y,x+30,y,'#334155');txt(g,String(k),x+34,y+3,'#475569',9)}txt(g,fm(val,1)+' '+u,x+11,H-6,c,12,'center')})};
D.calorimetro=(g,W,H,v,o)=>{const x=W/2-70,top=50,hh=H-90,t=Math.max(0,Math.min(1,(o.Tf-0)/90));const col='rgba('+Math.round(59+t*180)+','+Math.round(130-t*70)+','+Math.round(246-t*190)+',.6)';rect(g,x,top,140,hh,null,'#334155');rect(g,x+1,top+hh*0.25,138,hh*0.75-1,col);if(o._metal)rect(g,x+50,top+hh*0.55,40,30,o._mc||'#94a3b8','#334155');if(o._ice){const n=Math.min(8,Math.ceil(o._ice/25));for(let i=0;i<n;i++)rect(g,x+14+(i%4)*30,top+hh*0.28+Math.floor(i/4)*18,22,16,'rgba(224,242,254,.95)','#7dd3fc')}txt(g,'T final = '+fm(o.Tf,1)+' °C',W/2,28,'#0f172a',14,'center');txt(g,o._lab||'',W/2,H-14,'#475569',11,'center')};
D.enfria=(g,W,H,v,o,S)=>{const x0=46,y0=H-34,w=W-70,h=H-60,tm=60,a=15,b=85;line(g,x0,y0,x0+w,y0);line(g,x0,y0,x0,y0-h);const X=t=>x0+t/tm*w,Y=T=>y0-(T-a)/(b-a)*h;[20,40,60,80].forEach(T=>{txt(g,String(T),x0-4,Y(T)+3,'#64748b',9,'right');line(g,x0,Y(T),x0+w,Y(T),'#e2e8f0')});(S.cfg.curvas||[]).forEach((c,i)=>{g.strokeStyle=c.c;g.lineWidth=2;g.beginPath();for(let t=0;t<=v.t+1e-9;t+=1){t?g.lineTo(X(t),Y(c.f(t))):g.moveTo(X(t),Y(c.f(t)))}g.stroke();circ(g,X(v.t),Y(c.f(v.t)),4,c.c);txt(g,c.n,x0+w-4,14+i*13,c.c,11,'right')});g.lineWidth=1;txt(g,'t (min)',x0+w,y0+14,'#475569',10,'right');txt(g,'T (°C)',x0+4,12,'#475569',10)};
D.pulso=(g,W,H,v,o)=>{const y=H/2,x0=30,sc=(W-60)/6,N=70;const xp=o.x;for(let i=0;i<=N;i++){const xi=i/N*6;let dx=0,dy=0;const u=(xi-xp)/0.35,p=Math.exp(-u*u);if(v.tipo==='transversal')dy=-p*38;else dx=(-u*p)*0.5*sc*0.45;circ(g,x0+xi*sc+dx,y+dy,3,'#4f46e5')}line(g,x0,y+46,x0+6*sc,y+46,'#cbd5e1');for(let m=0;m<=6;m++){line(g,x0+m*sc,y+46,x0+m*sc,y+52,'#64748b');txt(g,String(m),x0+m*sc,y+64,'#64748b',10,'center')}txt(g,(v.tipo==='transversal'?'Onda transversal':'Onda longitudinal')+' · frente en x = '+fm(xp,2)+' m',W/2,22,'#0f172a',12,'center')};
D.reflex=(g,W,H,v,o)=>{const y=H/2,x0=20,sc=(W-60)/9,Ax=v.A0*5;line(g,x0,y,x0+9*sc,y,'#cbd5e1');line(g,x0+6*sc,y-50,x0+6*sc,y+50,'#334155',3);txt(g,v.medio==='libre'?'extremo libre':v.medio==='fijo'?'extremo fijo':'cambio de cuerda',x0+6*sc,y-58,'#475569',11,'center');const P=(xc,a,c)=>{g.strokeStyle=c;g.lineWidth=2;g.beginPath();for(let k=-12;k<=12;k++){const xx=xc+k*0.05,u=k*0.05/0.3,Y=y-a*Math.exp(-u*u)*5;const X=x0+xx*sc;k===-12?g.moveTo(X,Y):g.lineTo(X,Y)}g.stroke();g.lineWidth=1};const t=v.t,xi=3*t;if(xi<6)P(xi,v.A0,'#2563eb');else{if(o.Ar)P(6-(xi-6),o.Ar,'#dc2626');if(o.At)P(6+(xi-6)*(o._vt||1),o.At,'#16a34a')}txt(g,'azul: incidente · rojo: reflejado · verde: transmitido',W/2,H-8,'#64748b',11,'center')};
D.cubeta=(g,W,H,v,o)=>{rect(g,20,30,W-40,H-60,'rgba(56,189,248,.25)','#0369a1');const lam=o.lam*14;g.save();g.beginPath();g.rect(20,30,W-40,H-60);g.clip();g.strokeStyle='rgba(2,132,199,.7)';if(v.fuente==='plana'){for(let x=60;x<W-30;x+=lam)line(g,x,32,x,H-32,'rgba(2,132,199,.7)',2)}else{for(let r=lam;r<W;r+=lam){g.beginPath();g.arc(70,H/2,r,-1.2,1.2);g.stroke()}circ(g,70,H/2,5,'#0c4a6e')}g.restore();txt(g,'λ = '+fm(o.lam,2)+' cm',W/2,22,'#0f172a',13,'center')};
D.difrac=(g,W,H,v,o)=>{const bx=90,sx=W-110,top=14,hh=H-28;rect(g,bx-4,top,8,hh,'#334155');const n=v.tipo==='doble'?2:1,gap=v.tipo==='doble'?Math.min(70,v.d*9):0,cw=v.tipo==='doble'?12:Math.max(10,v.d*9);const cy=H/2;rect(g,bx-4,cy-gap/2-cw/2,8,cw,'#f8fafc');if(n===2)rect(g,bx-4,cy+gap/2-cw/2,8,cw,'#f8fafc');rect(g,sx-3,top,6,hh,'#e2e8f0','#94a3b8');const I=o._I;g.strokeStyle='#f59e0b';g.lineWidth=2;g.beginPath();for(let p=0;p<=hh;p++){const yy=(p-hh/2)/(hh/2)*o._ymax,Iv=I(yy);const X=sx+8+Iv*60,Y=top+p;p?g.lineTo(X,Y):g.moveTo(X,Y)}g.stroke();g.lineWidth=1;for(let p=0;p<=hh;p+=2){const yy=(p-hh/2)/(hh/2)*o._ymax,Iv=I(yy);line(g,sx-2,top+p,sx-2-Iv*10,top+p,'rgba(245,158,11,'+Iv+')',2)}for(let k=0;k<4;k++){g.strokeStyle='rgba(2,132,199,.5)';g.beginPath();g.arc(bx,cy,30+k*28,-0.8,0.8);g.stroke()}txt(g,o._txt||'',W/2,H-4,'#0f172a',12,'center')};
D.telefono=(g,W,H,v,o)=>{const y=H/2;circ(g,40,y,22,'#e2e8f0','#334155');circ(g,W-40,y,22,'#e2e8f0','#334155');const sag=o._sag||0;g.strokeStyle='#334155';g.lineWidth=2;g.beginPath();g.moveTo(62,y);g.quadraticCurveTo(W/2,y+sag*2,W-62,y);g.stroke();g.lineWidth=1;txt(g,'L = '+v.L+' m · '+o._n,W/2,24,'#0f172a',12,'center');txt(g,'tiempo = '+fm(o.t,2)+' ms · intensidad = '+fm(o.amp,1)+' %',W/2,H-12,'#475569',12,'center')};
D.vacio=(g,W,H,v,o)=>{const cx=W/2;g.strokeStyle='#334155';g.lineWidth=3;g.beginPath();g.moveTo(cx-90,H-30);g.lineTo(cx-90,50);g.quadraticCurveTo(cx,-10,cx+90,50);g.lineTo(cx+90,H-30);g.stroke();g.lineWidth=1;rect(g,cx-110,H-30,220,8,'#64748b');circ(g,cx,H-50,10,'#facc15','#a16207');const n=Math.max(0,Math.round(o.frac*5));for(let i=1;i<=n;i++){g.strokeStyle='rgba(79,70,229,'+(0.9-i*0.12)+')';g.beginPath();g.arc(cx,H-50,16+i*18,-2.4,-0.74);g.stroke()}txt(g,'presión = '+fm(v.p,0)+' kPa · nivel = '+fm(o.L,0)+' dB',cx,H-6,'#0f172a',13,'center')};
D.botella2=(g,W,H,v,o)=>{const x=W/2-30,top=20,hh=H-50,sc=hh/25;rect(g,x,top,60,hh,null,'#334155');rect(g,x+1,top+hh-v.w*sc,58,v.w*sc,'rgba(56,189,248,.5)');for(let i=0;i<4;i++){g.strokeStyle='rgba(79,70,229,'+(0.8-i*0.15)+')';g.beginPath();g.moveTo(x+10,top+8+i*0+0);g.stroke()}const L=25-v.w;line(g,x+75,top,x+75,top+L*sc,'#4f46e5',3);txt(g,'columna de aire L = '+fm(L,0)+' cm',x+85,top+L*sc/2,'#4f46e5',11);txt(g,'f = '+fm(o.f,0)+' Hz',W/2,H-6,'#0f172a',13,'center')};
D.diapason=(g,W,H,v,o)=>{const x1=W/2-90,x2=W/2+90,y=70;[[x1,'440 Hz',6],[x2,fm(v.fb,0)+' Hz',Math.max(1,o.A/100*8)]].forEach(([x,t,a])=>{line(g,x,y+60,x,y+120,'#334155',6);line(g,x-12,y,x-12,y+60,'#64748b',6);line(g,x+12,y,x+12,y+60,'#64748b',6);line(g,x-12-a,y,x-12+a,y,'rgba(79,70,229,.4)',3);txt(g,t,x,y+140,'#334155',12,'center')});txt(g,'Amplitud del 2.º diapasón: '+fm(o.A,0)+' %',W/2,24,'#0f172a',13,'center');rect(g,40,H-26,W-80,10,'#e2e8f0');rect(g,40,H-26,(W-80)*o.A/100,10,'#6366f1')};
D.eco=(g,W,H,v,o)=>{const y=H/2,wx=W-50,px=50;circ(g,px,y-16,10,'#fcd34d','#92400e');line(g,px,y-6,px,y+30,'#92400e',3);rect(g,wx,y-60,16,120,'#a8a29e','#44403c');line(g,px+14,y+50,wx-6,y+50,'#4f46e5',2);txt(g,'d = '+v.d+' m',W/2,y+70,'#334155',12,'center');txt(g,'T = '+v.T+' °C · tiempo de ida y vuelta = '+fm(o.t,2)+' s',W/2,22,'#0f172a',12,'center')};
D.tubo=(g,W,H,v,o)=>{const x=W/2-20,top=24,hh=H-50,sc=hh/65;rect(g,x,top,40,hh,null,'#334155');rect(g,x+1,top+v.L*sc,38,hh-v.L*sc,'rgba(56,189,248,.5)');g.strokeStyle='#4f46e5';g.lineWidth=2;g.beginPath();for(let k=0;k<=40;k++){const yy=top+k/40*v.L*sc,amp=Math.sin(Math.PI/2*k/40)*o.A*16;k?g.lineTo(x+20+amp,yy):g.moveTo(x+20+amp,yy)}g.stroke();g.lineWidth=1;circ(g,x+20,top-6,5,'#facc15','#a16207');txt(g,'L = '+fm(v.L,1)+' cm · '+v.f+' Hz',x+60,top+20,'#0f172a',12);txt(g,'volumen: '+fm(o.A*100,0)+' %',x+60,top+40,o.A>0.9?'#047857':'#475569',12)};
D.doppler=(g,W,H,v,o)=>{const cx=W/2-60,cy=H/2,r=Math.min(H/2-20,70);g.strokeStyle='#94a3b8';g.beginPath();g.arc(cx,cy,r,0,7);g.stroke();circ(g,cx+r,cy,8,'#f97316','#7c2d12');for(let k=1;k<=4;k++){g.strokeStyle='rgba(99,102,241,'+(0.9-k*0.15)+')';g.beginPath();g.arc(cx+r+k*10*(o._sh||1),cy-k*12,k*15,0,7);g.stroke()}circ(g,W-50,cy,10,'#22c55e','#14532d');txt(g,'observador',W-50,cy+28,'#14532d',11,'center');txt(g,'f cuando se acerca = '+fm(o.fa,0)+' Hz · cuando se aleja = '+fm(o.fl,0)+' Hz',W/2,H-8,'#0f172a',12,'center')};
/* ---- grado 9: óptica y electromagnetismo ---- */
const rad=a=>a*Math.PI/180;
D.estenopeica=(g,W,H,v,o)=>{const y=H/2,sc=Math.min(3.4,(W-120)/(v.do+v.dp)),xo=30,xh=xo+v.do*sc,xp=xh+v.dp*sc,ho=v.ho*4,hi=o.hi*4;line(g,xo,y,xp,y,'#cbd5e1');rect(g,xh-3,y-70,6,60,'#334155');rect(g,xh-3,y+10,6,60,'#334155');rect(g,xp-2,y-75,4,150,'#e2e8f0','#94a3b8');line(g,xo,y,xo,y-ho,'#16a34a',4);circ(g,xo,y-ho,5,'#16a34a');line(g,xp,y,xp,y+hi,'#16a34a',4);circ(g,xp,y+hi,4,'#16a34a');g.setLineDash([4,3]);line(g,xo,y-ho,xp,y+hi,'#f59e0b',1);line(g,xo,y,xp,y,'#f59e0b',1);g.setLineDash([]);txt(g,'objeto '+v.ho+' cm',xo,y-ho-10,'#166534',11);txt(g,'imagen invertida '+fm(o.hi,1)+' cm',xp,y+92,'#166534',11,'center');txt(g,'orificio ø '+fm(v.d,1)+' mm',xh,y-80,'#334155',11,'center');txt(g,'d₀ = '+v.do+' cm',(xo+xh)/2,H-10,'#475569',11,'center');txt(g,'dₚ = '+v.dp+' cm',(xh+xp)/2,H-24,'#475569',11,'center')};
D.espejo=(g,W,H,v,o)=>{const cx=W/2,cy=H-70,a=rad(v.ang),L=150;rect(g,cx-170,cy,340,8,'#94a3b8','#475569');for(let i=-16;i<=16;i++)line(g,cx+i*10,cy+8,cx+i*10-6,cy+15,'#64748b');g.setLineDash([5,4]);line(g,cx,cy,cx,cy-L-20,'#64748b');g.setLineDash([]);line(g,cx-Math.sin(a)*L,cy-Math.cos(a)*L,cx,cy,'#dc2626',3);line(g,cx,cy,cx+Math.sin(a)*L,cy-Math.cos(a)*L,'#2563eb',3);g.strokeStyle='#dc2626';g.beginPath();g.arc(cx,cy,48,-Math.PI/2-a,-Math.PI/2);g.stroke();g.strokeStyle='#2563eb';g.beginPath();g.arc(cx,cy,60,-Math.PI/2,-Math.PI/2+a);g.stroke();txt(g,'i = '+v.ang+'°',cx-90,cy-60,'#dc2626',12,'center');txt(g,'r = '+fm(o.r,1)+'°',cx+90,cy-60,'#2563eb',12,'center');txt(g,'normal',cx+4,cy-L-22,'#64748b',10)};
D.espejos2=(g,W,H,v,o)=>{const cx=W/2-20,cy=H/2+10,R=Math.min(100,H/2-30),al=rad(v.alpha),m=Math.round(360/v.alpha);g.lineWidth=5;line(g,cx,cy,cx+R*1.35,cy,'#475569',5);line(g,cx,cy,cx+Math.cos(al)*R*1.35,cy-Math.sin(al)*R*1.35,'#475569',5);g.lineWidth=1;for(let k=0;k<m;k++){const th=al/2+k*al,x=cx+Math.cos(th)*R*0.8,y=cy-Math.sin(th)*R*0.8;if(k===0){circ(g,x,y,9,'#f97316','#7c2d12');txt(g,'objeto',x+12,y-8,'#7c2d12',11)}else{circ(g,x,y,8,'rgba(99,102,241,.55)','#3730a3');txt(g,String(k),x,y+4,'#fff',10,'center')}}txt(g,'ángulo entre espejos = '+v.alpha+'°',W/2,20,'#0f172a',13,'center');txt(g,'imágenes formadas: '+o.n,W/2,H-8,'#4338ca',13,'center')};
D.optica=(g,W,H,v,o)=>{const lens=o._kind==='lente',ax=H/2,f=o._f,sc=Math.min(3.6,(W-140)/70),xm=lens?W/2:W-40,ho=34;line(g,10,ax,W-10,ax,'#cbd5e1');const X=d=>xm-d*sc;g.save();g.beginPath();g.rect(0,0,W,H);g.clip();
 if(lens){g.strokeStyle='#0ea5e9';g.lineWidth=3;g.beginPath();if(f>0){g.ellipse(xm,ax,9,70,0,0,7)}else{g.moveTo(xm-9,ax-70);g.quadraticCurveTo(xm+2,ax,xm-9,ax+70);g.moveTo(xm+9,ax-70);g.quadraticCurveTo(xm-2,ax,xm+9,ax+70)}g.stroke();g.lineWidth=1}
 else{g.strokeStyle='#0ea5e9';g.lineWidth=4;g.beginPath();if(f>0)g.arc(xm+140,ax,140,Math.PI-0.5,Math.PI+0.5);else g.arc(xm-140,ax,140,-0.5,0.5);g.stroke();g.lineWidth=1}
 const xf=lens?[xm-f*sc,xm+f*sc]:[xm-f*sc];xf.forEach(x=>{circ(g,x,ax,3,'#f59e0b');txt(g,'F',x,ax+14,'#b45309',10,'center')});
 const xo=X(v.do);line(g,xo,ax,xo,ax-ho,'#16a34a',4);circ(g,xo,ax-ho,4,'#16a34a');txt(g,'objeto',xo,ax+14,'#166534',10,'center');
 if(o.di!=null){const xi=lens?xm+o.di*sc:xm-o.di*sc,hi=-o.m*ho,virt=lens?o.di<0:o.di<0;g.setLineDash(virt?[4,3]:[]);line(g,xi,ax,xi,ax-hi,'#dc2626',4);circ(g,xi,ax-hi,4,'#dc2626');g.setLineDash([]);txt(g,virt?'imagen virtual':'imagen real',xi,hi>0?ax-hi-8:ax-hi+16,'#991b1b',10,'center');
  const yt=ax-ho;g.setLineDash(virt?[3,3]:[]);line(g,xo,yt,xm,yt,'#f59e0b',1);line(g,xm,yt,xi,ax-hi,'#f59e0b',1);line(g,xo,yt,xm,ax,'#a855f7',1);line(g,xm,ax,xi,ax-hi,'#a855f7',1);g.setLineDash([])}
 g.restore();txt(g,o._t||'',W/2,18,'#0f172a',12,'center')};
D.snell=(g,W,H,v,o)=>{const cy=H/2,cx=W/2,n=v.medio,L=110,a=rad(v.i),b=rad(o.r);rect(g,0,cy,W,H-cy,n>2?'rgba(167,139,250,.35)':'rgba(56,189,248,.3)');line(g,0,cy,W,cy,'#334155',2);g.setLineDash([5,4]);line(g,cx,cy-L-10,cx,cy+L+10,'#64748b');g.setLineDash([]);line(g,cx-Math.sin(a)*L,cy-Math.cos(a)*L,cx,cy,'#dc2626',3);line(g,cx,cy,cx+Math.sin(b)*L,cy+Math.cos(b)*L,'#dc2626',3);txt(g,'θ₁ = '+v.i+'°',cx-70,cy-30,'#b91c1c',12,'center');txt(g,'θ₂ = '+fm(o.r,1)+'°',cx+75,cy+55,'#b91c1c',12,'center');txt(g,'aire n = 1,00',12,20,'#475569',11);txt(g,'medio n = '+fm(n,2),12,H-10,'#0c4a6e',11)};
D.fibra=(g,W,H,v,o)=>{const cy=H/2,cx=W/2,L=110,a=rad(v.i);rect(g,0,cy,W,H-cy,'rgba(56,189,248,.3)');line(g,0,cy,W,cy,'#334155',2);g.setLineDash([5,4]);line(g,cx,cy-L,cx,cy+L,'#64748b');g.setLineDash([]);line(g,cx-Math.sin(a)*L,cy+Math.cos(a)*L,cx,cy,'#dc2626',3);line(g,cx,cy,cx+Math.sin(a)*L,cy+Math.cos(a)*L,'#dc2626',3*(o.R/100)+0.5);if(o.r!=null){const b=rad(o.r);line(g,cx,cy,cx+Math.sin(b)*L,cy-Math.cos(b)*L,'#f59e0b',3*(1-o.R/100)+1)}txt(g,o.tir?'REFLEXIÓN INTERNA TOTAL':'Parte sale al aire',cx,22,o.tir?'#047857':'#b45309',14,'center');txt(g,'ángulo en el medio = '+v.i+'° · n = '+fm(v.medio,2),12,H-10,'#0c4a6e',11);txt(g,'aire',12,cy-8,'#475569',11)};
D.telescopio=(g,W,H,v,o)=>{const ax=H/2,tot=v.fo+v.fe,sc=(W-130)/tot,x1=50,xF=x1+v.fo*sc,x2=x1+tot*sc,yF=ax+0.12*(xF-x1);rect(g,x1,ax-45,x2-x1,90,null,'#cbd5e1');[[x1,'objetivo'],[x2,'ocular']].forEach(([x,t])=>{g.strokeStyle='#0ea5e9';g.lineWidth=3;g.beginPath();g.ellipse(x,ax,6,40,0,0,7);g.stroke();g.lineWidth=1;txt(g,t,x,ax+58,'#0369a1',11,'center')});const m2=(ax-yF)/(x2-xF);[-24,0,24].forEach(h=>{const y1=ax+h;line(g,10,y1-0.12*(x1-10),x1,y1,'#f59e0b');line(g,x1,y1,x2,yF+(yF-y1)/(xF-x1)*(x2-xF),'#f59e0b');const ye=yF+(yF-y1)/(xF-x1)*(x2-xF);line(g,x2,ye,x2+70,ye+m2*70,'#f59e0b')});circ(g,xF,yF,3,'#b45309');txt(g,'foco común',xF-6,yF-12,'#b45309',10,'center');txt(g,'M = '+fm(o.M,1)+' ×  ·  tubo = '+fm(tot,0)+' cm',W/2,20,'#0f172a',13,'center')};
const NPR=l=>1.5046+4200/(l*l),DEV=(i,l,A)=>{const n=NPR(l),r1=Math.asin(Math.sin(rad(i))/n),r2=rad(A)-r1,s=n*Math.sin(r2);if(Math.abs(s)>1)return null;return i+Math.asin(s)*180/Math.PI-A};
const WLC=l=>l<=440?'#7c3aed':l<=490?'#2563eb':l<=560?'#16a34a':l<=600?'#eab308':'#dc2626';
D.prisma=(g,W,H,v,o)=>{const A=60,cx=W/2,by=H-40,hgt=130,px=[cx-75,by],py=[cx+75,by],pt=[cx,by-hgt];g.fillStyle='rgba(186,230,253,.5)';g.strokeStyle='#0369a1';g.beginPath();g.moveTo(px[0],px[1]);g.lineTo(py[0],py[1]);g.lineTo(pt[0],pt[1]);g.closePath();g.fill();g.stroke();const mx=(px[0]+pt[0])/2,my=(px[1]+pt[1])/2;line(g,mx-130,my+Math.tan(rad(v.i-30))*130*0.5+10,mx,my,'#64748b',3);const ex=(py[0]+pt[0])/2,ey=(py[1]+pt[1])/2;[400,470,530,580,650].forEach(l=>{const d=DEV(v.lam===l?v.i:v.i,l,A);if(d==null)return;const sel=l===v.lam;line(g,ex,ey,ex+170,ey+(d-30)*2.4+20,WLC(l),sel?4:1.5)});txt(g,'luz blanca',mx-110,my-14,'#475569',11);txt(g,sel0(v,o),W/2,18,'#0f172a',13,'center')};
const sel0=(v,o)=>o.d==null?'Reflexión total en la segunda cara':'Desviación δ = '+fm(o.d,1)+'°  (λ = '+v.lam+' nm)';
D.color=(g,W,H,v,o)=>{const cx=W/2-70,cy=H/2,r=54;if(v.modo==='luz'){rect(g,cx-100,cy-90,300,180,'#0f172a');g.globalCompositeOperation='lighter';[[cx,cy-26,'255,0,0',v.a],[cx-28,cy+24,'0,255,0',v.b],[cx+28,cy+24,'0,0,255',v.c]].forEach(([x,y,c,a])=>{g.fillStyle='rgba('+c+','+a/100+')';g.beginPath();g.arc(x,y,r,0,7);g.fill()});g.globalCompositeOperation='source-over'}else{rect(g,cx-100,cy-90,300,180,'#ffffff','#cbd5e1');g.globalCompositeOperation='multiply';[[cx,cy-26,'0,255,255',v.a],[cx-28,cy+24,'255,0,255',v.b],[cx+28,cy+24,'255,255,0',v.c]].forEach(([x,y,c,a])=>{g.fillStyle='rgba('+c+','+a/100+')';g.beginPath();g.arc(x,y,r,0,7);g.fill()});g.globalCompositeOperation='source-over'}rect(g,cx+130,cy-40,60,80,'rgb('+Math.round(o.cr)+','+Math.round(o.cg)+','+Math.round(o.cb)+')','#334155');txt(g,'resultado',cx+160,cy+58,'#334155',11,'center');txt(g,v.modo==='luz'?'Mezcla aditiva de luces (R, G, B)':'Mezcla sustractiva de pigmentos (C, M, A)',W/2,18,'#0f172a',12,'center')};
D.circuito=(g,W,H,v,o)=>{const x0=60,x1=W-60,y0=60,y1=H-50;g.strokeStyle='#334155';g.lineWidth=3;g.beginPath();g.moveTo(x0,y1);g.lineTo(x0,y0);g.lineTo(x0+70,y0);g.moveTo(x0+140,y0);g.lineTo(x1-60,y0);g.moveTo(x1-60,y0);g.lineTo(x1,y0);g.lineTo(x1,y1);g.lineTo(x0,y1);g.stroke();g.lineWidth=1;line(g,x0+70,y0,x0+140,y0-(v.sw==='cerrado'?0:28),'#475569',4);circ(g,x0+70,y0,4,'#475569');circ(g,x0+140,y0,4,'#475569');txt(g,'interruptor '+v.sw,x0+105,y0-38,'#475569',11,'center');for(let i=0;i<v.n;i++){rect(g,x0-14,y1-30-(i+1)*20,28,16,'#fde047','#a16207');txt(g,'1,5 V',x0,y1-30-i*20-8,'#713f12',9,'center')}const gl=Math.min(1,o.P/0.9);circ(g,x1,(y0+y1)/2,26+gl*14,'rgba(253,224,71,'+(gl*0.45)+')');circ(g,x1,(y0+y1)/2,22,gl>0.01?'rgb(254,240,138)':'#e5e7eb','#a16207');txt(g,v.rb+' Ω',x1,(y0+y1)/2+4,'#713f12',11,'center');txt(g,'V = '+fm(o.V,1)+' V · I = '+fm(o.I,0)+' mA',W/2,H-14,'#0f172a',13,'center')};
D.conduct=(g,W,H,v,o)=>{const y=H/2;rect(g,W/2-60,y-30,120,60,'#f1f5f9','#334155');txt(g,o._n,W/2,y+4,'#0f172a',13,'center');circ(g,50,y,16,'#fde047','#a16207');txt(g,'4,5V',50,y+4,'#713f12',9,'center');g.strokeStyle='#334155';g.lineWidth=2;g.beginPath();g.moveTo(66,y);g.lineTo(W/2-60,y);g.moveTo(W/2+60,y);g.lineTo(W-90,y);g.stroke();g.lineWidth=1;circ(g,W-62,y,28,'#fff','#334155');txt(g,'mA',W-62,y-4,'#475569',10,'center');txt(g,fm(o.I,1),W-62,y+12,'#0f172a',12,'center');const on=o.I>1;circ(g,W/2,y-70,16+(on?6:0),on?'rgb(254,240,138)':'#e5e7eb','#a16207');txt(g,on?'conduce':'aísla',W/2,y-34,on?'#047857':'#b91c1c',12,'center')};
D.electroiman=(g,W,H,v,o)=>{const cx=W/2,y=70;rect(g,cx-8,y,16,90,'#94a3b8','#475569');g.strokeStyle='#b45309';g.lineWidth=2;const n=Math.min(40,v.N/2.5);for(let i=0;i<n;i++){const yy=y+6+i*(78/Math.max(n,1));line(g,cx-14,yy,cx+14,yy+4,'#b45309',2)}g.lineWidth=1;line(g,cx-14,y+10,cx-80,y-30,'#b45309',2);line(g,cx+14,y+80,cx+80,y+50,'#b45309',2);rect(g,cx+60,y+26,22,36,'#fde047','#a16207');txt(g,fm(v.I,1)+' A',cx+71,y+48,'#713f12',10,'center');const k=Math.min(o.clips,36);for(let i=0;i<k;i++){const c=i%6,r=Math.floor(i/6);circ(g,cx-22+c*9,y+104+r*8,3.5,null,'#475569')}txt(g,'clips levantados: '+fm(o.clips,0),cx,H-14,'#0f172a',13,'center');txt(g,'N = '+v.N+' vueltas',cx-110,y+40,'#b45309',11,'center')};
D.homopolar=(g,W,H,v,o)=>{const cx=W/2,y=40;rect(g,cx-14,y+26,28,60,'#fde047','#a16207');txt(g,'pila',cx,y+60,'#713f12',10,'center');rect(g,cx-26,y+86,52,18,v.polo==='N'?'#dc2626':'#2563eb','#334155');txt(g,'polo '+v.polo,cx,y+99,'#fff',10,'center');g.strokeStyle='#b45309';g.lineWidth=3;g.beginPath();g.moveTo(cx,y+26);g.quadraticCurveTo(cx-60,y+60,cx-40,y+100);g.moveTo(cx,y+26);g.quadraticCurveTo(cx+60,y+60,cx+40,y+100);g.stroke();g.lineWidth=1;txt(g,o.rpm>=0?'↻ gira en sentido horario':'↺ gira en sentido antihorario',cx,H-30,'#4338ca',13,'center');txt(g,'velocidad = '+fm(o.rpm,0)+' rpm',cx,H-10,'#0f172a',13,'center')};
D.bobina=(g,W,H,v,o)=>{const cx=W/2-30,y=H/2;for(let i=0;i<Math.min(14,v.N/30);i++){circ(g,cx-45+i*7,y,34,null,'#b45309')}const mx=v.sentido==='entra'?cx-110:cx+30;rect(g,mx,y-12,60,24,'#dc2626','#334155');rect(g,mx+30,y-12,30,24,'#2563eb','#334155');txt(g,'N',mx+15,y+4,'#fff',11,'center');txt(g,'S',mx+45,y+4,'#fff',11,'center');txt(g,v.sentido==='entra'?'→ entra':'← sale',mx+30,y+52,'#475569',11,'center');const gx=W-70,gy=y+10;circ(g,gx,gy,40,'#fff','#334155');const ang=Math.max(-1.2,Math.min(1.2,o.eps/150));line(g,gx,gy+14,gx+Math.sin(ang)*34,gy+14-Math.cos(ang)*34,'#dc2626',3);txt(g,'galvanómetro',gx,gy+58,'#475569',10,'center');txt(g,'ε = '+fm(o.eps,0)+' mV · v = '+v.v+' cm/s · '+v.N+' espiras',W/2,H-10,'#0f172a',12,'center')};

/* ---- grado 10: mecánica ---- */
const ARW=(g,x1,y1,x2,y2,c,w)=>{line(g,x1,y1,x2,y2,c,w||2);const a=Math.atan2(y2-y1,x2-x1);g.fillStyle=c;g.beginPath();g.moveTo(x2,y2);g.lineTo(x2-8*Math.cos(a-0.4),y2-8*Math.sin(a-0.4));g.lineTo(x2-8*Math.cos(a+0.4),y2-8*Math.sin(a+0.4));g.fill()};
D.tuboburb=(g,W,H,v,o)=>{const a=rad(v.ang),L=Math.min(W-120,300),x0=60,y0=H-50;g.save();g.translate(x0,y0);g.rotate(-a);rect(g,0,-12,L,24,'rgba(250,204,21,.45)','#334155');for(let k=0;k<=6;k++){line(g,k*L/6,12,k*L/6,18,'#64748b');txt(g,String(k*10),k*L/6,30,'#64748b',9,'center')}circ(g,Math.min(L,o.x/60*L),0,7,'rgba(255,255,255,.95)','#334155');g.restore();txt(g,'inclinación '+v.ang+'° · posición de la burbuja x = '+fm(o.x,1)+' cm',W/2,20,'#0f172a',12,'center')};
D.rampa=(g,W,H,v,o)=>{const a=rad(v.ang),L=Math.min(W-100,330),x0=40,y0=H-40;g.fillStyle='#e2e8f0';g.beginPath();g.moveTo(x0,y0);g.lineTo(x0+L*Math.cos(a),y0);g.lineTo(x0+L*Math.cos(a),y0-L*Math.sin(a));g.closePath();g.fill();g.strokeStyle='#475569';g.stroke();const p=(o.pos==null?0:o.pos),s=L*(1-p*0.85)-30;g.save();g.translate(x0+s*Math.cos(a),y0-s*Math.sin(a));g.rotate(-a);rect(g,-14,-22,28,22,o.slip?'#f87171':'#818cf8','#1e1b4b');g.restore();g.strokeStyle='#334155';g.beginPath();g.arc(x0+L*Math.cos(a),y0,40,Math.PI,Math.PI+a);g.stroke();txt(g,v.ang+'°',x0+L*Math.cos(a)-60,y0-6,'#334155',12);txt(g,o._txt||'',W/2,20,'#0f172a',12,'center')};
D.caida=(g,W,H,v,o)=>{const x=W/2,top=40,base=H-40,sc=(base-top)/2;line(g,x-60,base,x+60,base,'#334155',3);rect(g,x+40,top,6,base-top,'#e2e8f0','#94a3b8');for(let k=0;k<=4;k++){const y=base-k*0.5*sc;line(g,x+46,y,x+54,y,'#64748b');txt(g,fm(k*0.5,1)+' m',x+58,y+3,'#64748b',9)}circ(g,x,base-v.h*sc,9,'#f97316','#7c2d12');rect(g,x-30,base-6,60,6,'#22c55e');txt(g,'fotopuerta inferior',x-36,base+16,'#166534',10);txt(g,'h = '+fm(v.h,2)+' m · tiempo de caída = '+fm(o.t,3)+' s',W/2,20,'#0f172a',12,'center')};
D.proy=(g,W,H,v,o)=>{const T=o._T,vx=o._vx,vy=o._vy,h0=o._h0,g0=9.8;let xm=0,ym=h0;const N=60,pts=[];for(let i=0;i<=N;i++){const t=T*i/N,x=vx*t,y=h0+vy*t-0.5*g0*t*t;pts.push([x,y]);xm=Math.max(xm,x);ym=Math.max(ym,y)}const sc=Math.min((W-100)/Math.max(xm,1),(H-90)/Math.max(ym,1)),x0=50,y0=H-40;line(g,x0-20,y0,W-20,y0,'#475569',2);if(h0>0)rect(g,x0-30,y0-h0*sc,30,h0*sc,'#d6b370','#78350f');g.strokeStyle='#4f46e5';g.lineWidth=2;g.beginPath();pts.forEach((p,i)=>{const X=x0+p[0]*sc,Y=y0-p[1]*sc;i?g.lineTo(X,Y):g.moveTo(X,Y)});g.stroke();g.lineWidth=1;circ(g,x0+xm*sc,y0,5,'#dc2626');txt(g,o._txt||'',W/2,18,'#0f172a',12,'center')};
D.colgante=(g,W,H,v,o)=>{const cx=W/2,py=H/2+10,a1=rad(v.a1),a2=rad(v.a2),L=120;rect(g,0,20,W,6,'#94a3b8');line(g,cx,py,cx-L*Math.cos(a1),py-L*Math.sin(a1),'#334155',3);line(g,cx,py,cx+L*Math.cos(a2),py-L*Math.sin(a2),'#334155',3);line(g,cx,py,cx,py+40,'#334155',2);rect(g,cx-16,py+40,32,28,'#6366f1','#1e1b4b');txt(g,fm(v.m,0)+' g',cx,py+58,'#fff',10,'center');txt(g,'T₁ = '+fm(o.T1,2)+' N',cx-L*Math.cos(a1)/2-30,py-L*Math.sin(a1)/2-8,'#b91c1c',12,'center');txt(g,'T₂ = '+fm(o.T2,2)+' N',cx+L*Math.cos(a2)/2+30,py-L*Math.sin(a2)/2-8,'#b91c1c',12,'center');txt(g,'α₁ = '+v.a1+'°',cx-60,py-6,'#475569',11,'center');txt(g,'α₂ = '+v.a2+'°',cx+60,py-6,'#475569',11,'center')};
D.carro=(g,W,H,v,o)=>{const y=H/2+20,x=W/2-40;rect(g,20,y+22,W-40,6,'#94a3b8');rect(g,x,y-10,110,28,'#38bdf8','#0369a1');circ(g,x+20,y+22,8,'#334155');circ(g,x+90,y+22,8,'#334155');const sh=Math.min(60,(o.d||0)*2.2);rect(g,x+35+sh,y-34,40,24,o.slip?'#f87171':'#a78bfa','#312e81');txt(g,o.slip?'el bloque se desliza hacia adelante':'el bloque se mueve con el carrito',W/2,24,o.slip?'#b91c1c':'#047857',13,'center');ARW(g,x-40,y+4,x-4,y+4,'#dc2626',3);txt(g,'frenado a = '+v.a+' m/s²',x-30,y-14,'#b91c1c',11,'center');txt(g,'desplazamiento relativo = '+fm(o.d||0,1)+' cm',W/2,H-10,'#0f172a',12,'center')};
D.atwood=(g,W,H,v,o)=>{const y=70;rect(g,30,y,300,8,'#d6b370','#78350f');circ(g,350,y+4,16,'#e2e8f0','#334155');const cx=40+Math.min(60,o.a*14);rect(g,cx,y-24,70,24,'#38bdf8','#0369a1');txt(g,fm(v.M,0)+' g',cx+35,y-8,'#0c4a6e',11,'center');line(g,cx+70,y-12,350,y-12,'#334155');line(g,366,y+4,366,y+80+v.m/4,'#334155');rect(g,350,y+80+v.m/4,32,22,'#f97316','#7c2d12');txt(g,fm(v.m,0)+' g',366,y+96+v.m/4,'#fff',10,'center');txt(g,'aceleración a = '+fm(o.a,2)+' m/s²',W/2,H-14,'#0f172a',13,'center')};
D.choque=(g,W,H,v,o)=>{const rows=[['ANTES',o._u1,o._u2,H/2-60],['DESPUÉS',o._v1,o._v2,H/2+50]];rows.forEach(([t,a,b,y])=>{txt(g,t,14,y-30,'#475569',11);rect(g,20,y+22,W-40,4,'#94a3b8');const w1=14+o._m1/25,w2=14+o._m2/25;rect(g,W/2-110-w1/2,y-w1+22,w1,w1,'#6366f1','#1e1b4b');rect(g,W/2+110-w2/2,y-w2+22,w2,w2,'#f97316','#7c2d12');if(a)ARW(g,W/2-110,y-w1-4,W/2-110+a*30,y-w1-4,'#4338ca',3);if(b)ARW(g,W/2+110,y-w2-4,W/2+110+b*30,y-w2-4,'#c2410c',3);txt(g,'v₁ = '+fm(a||0,2),W/2-110,y+44,'#4338ca',11,'center');txt(g,'v₂ = '+fm(b||0,2),W/2+110,y+44,'#c2410c',11,'center')});txt(g,'m₁ = '+o._m1+' g · m₂ = '+o._m2+' g',W/2,16,'#0f172a',12,'center')};
D.centripeta=(g,W,H,v,o)=>{const cx=W/2,cy=H/2+4,R=Math.min(110,H/2-20),r=v.r/1.0*R*0.95,ang=(Date.now()/1000)%6.28*0;g.strokeStyle='#cbd5e1';g.setLineDash([4,4]);g.beginPath();g.arc(cx,cy,r,0,7);g.stroke();g.setLineDash([]);const bx=cx+r*0.7,by=cy-r*0.714;circ(g,cx,cy,10,'#64748b');line(g,cx,cy,bx,by,'#334155',2);circ(g,bx,by,9,'#f97316','#7c2d12');ARW(g,bx,by,bx-(bx-cx)*0.5,by-(by-cy)*0.5,'#dc2626',3);ARW(g,bx,by,bx+(by-cy)*0.6,by-(bx-cx)*0.6,'#16a34a',2);txt(g,'Fc',bx-(bx-cx)*0.55-8,by-(by-cy)*0.55-6,'#b91c1c',11);txt(g,'v',bx+(by-cy)*0.6+4,by-(bx-cx)*0.6,'#166534',11);txt(g,'r = '+fm(v.r,1)+' m · f = '+fm(v.f,1)+' Hz · Fc = '+fm(o.Fc,2)+' N',W/2,18,'#0f172a',12,'center');txt(g,'Peso colgante equivalente = '+fm(o.mc,0)+' g',W/2,H-10,'#475569',11,'center')};
D.resortes2=(g,W,H,v,o)=>{const cx=W/2,top=26,sp=(x,y,len)=>{g.strokeStyle='#334155';g.lineWidth=2;g.beginPath();g.moveTo(x,y);for(let i=0;i<=12;i++)g.lineTo(x+(i%2?8:-8),y+len*i/12);g.stroke();g.lineWidth=1};rect(g,cx-90,top-8,180,8,'#94a3b8');const ex=o.x*4,m=v.m;if(v.cfg==='ser'){sp(cx,top,50+ex*0.5);sp(cx,top+50+ex*0.5,50+ex*0.5);rect(g,cx-20,top+100+ex+2,40,20+m/30,'#6366f1','#1e1b4b')}else if(v.cfg==='par'){sp(cx-30,top,70+ex);sp(cx+30,top,70+ex);rect(g,cx-50,top+70+ex+2,100,16+m/30,'#6366f1','#1e1b4b')}else{sp(cx,top,70+ex);rect(g,cx-20,top+70+ex+2,40,20+m/30,'#6366f1','#1e1b4b')}txt(g,fm(m,0)+' g · x = '+fm(o.x,1)+' cm',cx+80,top+60,'#0f172a',12);txt(g,v.cfg==='ser'?'Resortes en serie':v.cfg==='par'?'Resortes en paralelo':'Un resorte',cx-100,top+8,'#475569',11,'right')};
D.montana=(g,W,H,v,o)=>{const x0=30,sw=W-60,base=H-30,sc=(H-70)/5.2,f=u=>base-(v.H*(Math.pow(Math.cos(u*Math.PI),2)*0.8+0.2*(1-u))-0)*sc*0.98;g.strokeStyle='#334155';g.lineWidth=3;g.beginPath();for(let i=0;i<=100;i++){const u=i/100,X=x0+u*sw,Y=base-(v.H*(1-u)*(1-u)*(0.5*(1+Math.cos(u*Math.PI*0)) )+0)*sc;i?g.lineTo(X,Y):g.moveTo(X,Y)}g.stroke();g.lineWidth=1;line(g,x0,base,x0+sw,base,'#94a3b8');g.setLineDash([4,3]);line(g,x0,base-v.H*sc,x0+sw,base-v.H*sc,'#f59e0b');g.setLineDash([]);const hh=Math.min(v.h,v.H),u=1-Math.sqrt(hh/v.H);circ(g,x0+u*sw,base-hh*sc-8,8,'#ef4444','#7f1d1d');txt(g,'altura inicial H = '+fm(v.H,1)+' m',x0+sw,base-v.H*sc-6,'#b45309',11,'right');txt(g,'h = '+fm(hh,1)+' m · v = '+fm(o.v,2)+' m/s',W/2,18,'#0f172a',12,'center')};
D.frenado=(g,W,H,v,o)=>{const y=H/2+20,sc=Math.min(30,(W-140)/Math.max(o.d,1));rect(g,20,y+16,W-40,6,'#94a3b8');for(let k=0;k<=o.d;k+=Math.max(1,Math.round(o.d/8)))line(g,60+k*sc,y+22,60+k*sc,y+28,'#64748b');rect(g,60,y-18,34,34,'#a78bfa','#312e81');ARW(g,98,y,98+Math.min(60,v.v0*14),y,'#16a34a',3);rect(g,60+o.d*sc,y-18,34,34,'rgba(167,139,250,.45)','#312e81');txt(g,'v₀ = '+fm(v.v0,0)+' m/s',70,y-26,'#166534',11);txt(g,'distancia de frenado d = '+fm(o.d,2)+' m',W/2,H-20,'#0f172a',13,'center');txt(g,'μ = '+v.mu+' · trabajo de la fricción = '+fm(o.W,1)+' J',W/2,18,'#475569',12,'center')};
D.escalera=(g,W,H,v,o)=>{const x0=40,y0=H-30,n=Math.round(v.h*2),sw=(W-220)/n,sh=(H-80)/n;g.strokeStyle='#334155';g.beginPath();g.moveTo(x0,y0);for(let i=0;i<n;i++){g.lineTo(x0+i*sw,y0-(i+1)*sh);g.lineTo(x0+(i+1)*sw,y0-(i+1)*sh)}g.stroke();circ(g,x0+n*sw*0.6,y0-n*sh*0.6-20,8,'#f59e0b','#78350f');line(g,x0+n*sw*0.6,y0-n*sh*0.6-12,x0+n*sw*0.6,y0-n*sh*0.6+8,'#78350f',3);txt(g,'altura '+v.h+' m · masa '+v.m+' kg',W-20,40,'#0f172a',12,'right');txt(g,'trabajo = '+fm(o.W,0)+' J',W-20,64,'#475569',12,'right');txt(g,'potencia = '+fm(o.P,0)+' W',W-20,90,'#047857',14,'right');txt(g,'tiempo '+v.t+' s',W-20,114,'#475569',12,'right')};
D.rebote=(g,W,H,v,o)=>{const base=H-34,sc=(H-70)/2.1,x=W/2-50;line(g,40,base,W-40,base,'#334155',3);for(let k=0;k<=2;k+=0.5){line(g,x+60,base-k*sc,x+68,base-k*sc,'#64748b');txt(g,fm(k,1)+' m',x+74,base-k*sc+3,'#64748b',9)}circ(g,x,base-v.h0*sc,9,'#fb923c','#7c2d12');txt(g,'h₀ = '+fm(v.h0,2),x-14,base-v.h0*sc-12,'#7c2d12',11,'right');circ(g,x+110,base-o.hr*sc,9,'#fb923c','#7c2d12');line(g,x+110,base-o.hr*sc,x+110,base,'#fcd34d');txt(g,'rebote h = '+fm(o.hr,2)+' m',x+124,base-o.hr*sc,'#0f172a',12)};
D.balistico=(g,W,H,v,o)=>{const cx=W/2,top=30,L=130,a=o.th;rect(g,cx-60,top-8,120,8,'#94a3b8');line(g,cx,top,cx+L*Math.sin(a),top+L*Math.cos(a),'#334155',2);rect(g,cx+L*Math.sin(a)-18,top+L*Math.cos(a),36,26,'#d6b370','#78350f');g.setLineDash([4,4]);line(g,cx,top,cx,top+L+26,'#94a3b8');g.setLineDash([]);g.strokeStyle='#cbd5e1';g.beginPath();g.arc(cx,top,L,Math.PI/2-a,Math.PI/2);g.stroke();txt(g,'altura alcanzada h = '+fm(o.h,1)+' cm',W/2,H-12,'#0f172a',13,'center');txt(g,v.can?('Cañón '+v.can+' · bloque '+fm(v.M,1)+' kg · bala '+v.m+' g'):'',W/2,H-32,'#475569',11,'center')};
D.silla=(g,W,H,v,o)=>{const cx=W/2-40,y=H/2+30;circ(g,cx,y-52,14,'#fcd34d','#92400e');rect(g,cx-14,y-38,28,60,'#60a5fa','#1e3a8a');rect(g,cx-22,y+30,44,8,'#334155');const r=(v.r2/0.8)*100+0;line(g,cx-14,y-28,cx-14-r,y-28,'#92400e',5);line(g,cx+14,y-28,cx+14+r,y-28,'#92400e',5);circ(g,cx-14-r,y-28,8+v.m*1.5,'#475569');circ(g,cx+14+r,y-28,8+v.m*1.5,'#475569');txt(g,'brazos recogidos: r = '+fm(v.r2,1)+' m (pesas de '+v.m+' kg)',W/2,H-10,'#475569',11,'center');txt(g,'ω inicial = '+fm(v.w1,1)+' rad/s  →  ω final = '+fm(o.w2,2)+' rad/s',W/2,20,'#0f172a',13,'center')};

E._D=D;E._util={esc,fm,$,btn,lab,rnd,gauss,quant,dec,panel,mkRetos,fit,line,txt,rect,circ};
/* ================= MOTOR BANCO ================= */
E.banco=(el,cfg,ctx)=>{
 const VR=cfg.vars||[],OUT=cfg.outs||[],T=cfg.tareas||[],G=cfg.graf,seed0=cfg.seed||(Math.random()*1e9|0);
 const S={v:{},rows:[],ti:0,ok:{},msg:'',n:0,last:null,play:0,cfg,rd:{},nc:0};
 VR.forEach(x=>S.v[x.id]=x.v!=null?x.v:(x.tipo==='sel'?x.opts[0][0]:x.min));
 const num=x=>VR.find(y=>y.id===x.id).tipo==='sel'?x:+x;
 const model=()=>cfg.fx(S.v,S);
 const outInfo=id=>OUT.find(o=>o.id===id)||{id,n:id,u:''};
 const read=o=>{const R={},rr=rnd(seed0+S.n*131+7);OUT.forEach(k=>{if(o[k.id]==null)return;const res=(o._res&&o._res[k.id])||k.res||0,sd=(o._sd&&o._sd[k.id]!=null)?o._sd[k.id]:(k.sd!=null?k.sd:(res?res*0.4:0));R[k.id]=quant(o[k.id]+(sd?gauss(rr)*sd:0),res);R['_d'+k.id]=dec(res)});return R};
 const fmtR=(k,R)=>fm(R[k.id],R['_d'+k.id]!=null?R['_d'+k.id]:(k.d!=null?k.d:2));
 el.innerHTML=`<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:12px">
  <div>${panel('🎛️ Controles',`<div id="fb_ctl"></div><div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:10px">${cfg.sinMedir?'':btn('fb_m','📏 Medir y registrar','#16a34a')}${cfg.anim?btn('fb_p','▶ Simular','#4f46e5'):''}${cfg.sinMedir?'':btn('fb_c','🗑 Borrar tabla','#64748b')}</div><div id="fb_rd" style="margin-top:10px;font-size:13px"></div>`)}</div>
  <div>${panel('🔬 Banco de experimentos',`<canvas id="fb_cv" width="520" height="${cfg.alto||260}" style="width:100%;background:#f8fafc;border-radius:10px;border:1px solid #e2e8f0"></canvas><div id="fb_lv" style="font-size:12px;color:#475569;margin-top:4px"></div>`)}</div></div>
  <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:12px;margin-top:12px"><div>${cfg.sinMedir?'':panel('📋 Tabla de datos','<div id="fb_tb" style="max-height:200px;overflow:auto;font-size:12px"></div>')}${G?panel('📈 Gráfica','<div id="fb_gr"></div>'):''}</div>
  <div>${panel('✅ Tareas','<div id="fb_tk"></div>')}<div id="fb_rt" style="margin-top:10px;background:#fffbeb;border:1.5px solid #fcd34d;border-radius:10px;padding:8px;font-size:13px"></div><div id="fb_fb" style="margin-top:8px;font-size:13px;font-weight:700"></div></div></div>`;
 const U=mkRetos(el,cfg.retos||[],ctx,'fb');
 const cv=$(el,'#fb_cv'),g=cv.getContext('2d');
 const draw=()=>{const o=model();g.clearRect(0,0,cv.width,cv.height);const d=D[cfg.vis]||D.barras;try{d(g,cv.width,cv.height,S.v,o,S)}catch(x){D.barras(g,cv.width,cv.height,o,o,S)}
  $(el,'#fb_lv').textContent=cfg.leyenda?cfg.leyenda(S.v,o):'';return o};
 const ctl=()=>{$(el,'#fb_ctl').innerHTML=VR.map(x=>x.tipo==='sel'?lab(esc(x.n))+`<select data-v="${x.id}" style="width:100%;padding:7px;border:1.5px solid #cbd5e1;border-radius:9px;font-weight:700;margin-top:3px">${x.opts.map(o=>`<option value="${esc(o[0])}" ${String(o[0])===String(S.v[x.id])?'selected':''}>${esc(o[1])}</option>`).join('')}</select>`:`<label style="display:block;font-size:12px;font-weight:800;margin-top:8px">${esc(x.n)}: <b id="fbv_${x.id}">${fm(S.v[x.id],dec(x.step||1))}</b> ${esc(x.u||'')}</label><input data-v="${x.id}" type="range" min="${x.min}" max="${x.max}" step="${x.step||1}" value="${S.v[x.id]}" style="width:100%">`).join('');
  el.querySelectorAll('#fb_ctl [data-v]').forEach(i=>{const f=()=>{const x=VR.find(y=>y.id===i.dataset.v);S.v[x.id]=x.tipo==='sel'?(isNaN(+i.value)||x.txt?i.value:+i.value):+i.value;const b=$(el,'#fbv_'+x.id);if(b)b.textContent=fm(S.v[x.id],dec(x.step||1));ctx.act('cambia',{});draw()};i.oninput=f;i.onchange=f})};
 const tabla=()=>{const cols=cfg.tabla||[];const h='<tr>'+cols.map(c=>`<th style="padding:3px 6px;text-align:left;border-bottom:2px solid #e2e8f0">${esc((VR.find(x=>x.id===c)||outInfo(c)).n)}${(VR.find(x=>x.id===c)||outInfo(c)).u?' ('+esc((VR.find(x=>x.id===c)||outInfo(c)).u)+')':''}</th>`).join('')+'</tr>';
  if(!$(el,'#fb_tb'))return;$(el,'#fb_tb').innerHTML=S.rows.length?`<table style="border-collapse:collapse;width:100%">${h}${S.rows.map(r=>'<tr>'+cols.map(c=>`<td style="padding:3px 6px;border-top:1px solid #e2e8f0">${esc(r[c])}</td>`).join('')+'</tr>').join('')}</table>`:'<span style="color:#64748b">Aún no hay medidas. Pulsa «Medir y registrar».</span>'};
 const grafica=()=>{if(!G)return;const pts=S.rows.map(r=>[r._gx,r._gy]).filter(p=>isFinite(p[0])&&isFinite(p[1]));const box=$(el,'#fb_gr');if(pts.length<1){box.innerHTML='<span style="color:#64748b;font-size:12px">Registra medidas para ver la gráfica.</span>';return}
  const W=360,H=210,m=38,xs=pts.map(p=>p[0]),ys=pts.map(p=>p[1]),mx=Math.max(...xs,1e-9)*1.1,my=Math.max(...ys.map(Math.abs),1e-9)*1.1,mi=Math.min(0,...ys)*1.1;const X=x=>m+x/mx*(W-m-10),Y=y=>H-m-(y-mi)/(my-mi)*(H-m-10);
  const f=pts.length>1?fit(xs,ys,G.origen):null;let s=`<svg viewBox="0 0 ${W} ${H}" style="width:100%;background:#fff;border:1px solid #e2e8f0;border-radius:8px"><line x1="${m}" y1="${H-m}" x2="${W-6}" y2="${H-m}" stroke="#334155"/><line x1="${m}" y1="6" x2="${m}" y2="${H-m}" stroke="#334155"/><text x="${W-6}" y="${H-10}" font-size="10" text-anchor="end" fill="#475569">${esc(G.nx)}</text><text x="${m+4}" y="12" font-size="10" fill="#475569">${esc(G.ny)}</text>`;
  [0,.5,1].forEach(k=>{s+=`<text x="${m-4}" y="${Y(mi+(my-mi)*k)+3}" font-size="9" text-anchor="end" fill="#64748b">${fm(mi+(my-mi)*k,2)}</text><text x="${X(mx*k)}" y="${H-m+12}" font-size="9" text-anchor="middle" fill="#64748b">${fm(mx*k,2)}</text>`});
  if(f)s+=`<line x1="${X(0)}" y1="${Y(f.b)}" x2="${X(mx)}" y2="${Y(f.m*mx+f.b)}" stroke="#a5b4fc" stroke-width="2"/>`;pts.forEach(p=>{s+=`<circle cx="${X(p[0])}" cy="${Y(p[1])}" r="4" fill="#4f46e5"/>`});s+='</svg>';
  box.innerHTML=s+(f?`<div style="font-size:12px;margin-top:4px">Ajuste lineal: <b>pendiente = ${fm(f.m,3)}</b>${G.origen?'':' · intercepto = '+fm(f.b,3)} ${esc(G.u||'')}</div>`:'')};
 const tareas=()=>{const t=T[S.ti];const box=$(el,'#fb_tk');if(!t){box.innerHTML='<span style="color:#64748b">Este laboratorio no tiene tareas; haz los retos.</span>';return}
  const done=Object.keys(S.ok).length;box.innerHTML=`<div style="font-size:12px;color:#64748b">Tarea ${S.ti+1} de ${T.length} · completadas: ${done}</div><div style="margin:6px 0;font-size:13px"><b>${esc(t.txt)}</b></div>${(t.t==='valor')?`<input id="fb_in" type="number" step="any" placeholder="Tu respuesta${t.u?' ('+esc(t.u)+')':''}" value="${S.rd[S.ti]!=null?S.rd[S.ti]:''}" style="width:100%;padding:8px;border:1.5px solid #cbd5e1;border-radius:9px">`:''}<div style="display:flex;gap:6px;margin-top:8px">${btn('fb_ck','Comprobar','#4f46e5')}${btn('fb_nx','Siguiente tarea ▶','#64748b')}</div><div id="fb_msg" style="margin-top:6px;font-size:13px;font-weight:700">${esc(S.msg)}</div>`;
  $(el,'#fb_ck').onclick=()=>{const tt=T[S.ti];let ok=false,msg='';
   if(tt.t==='valor'){const x=+$(el,'#fb_in').value;S.rd[S.ti]=$(el,'#fb_in').value===''?null:x;if($(el,'#fb_in').value===''){msg='Escribe tu respuesta.'}else{const a=typeof tt.ans==='function'?tt.ans(S.v,S):tt.ans;const tol=tt.tolA!=null?tt.tolA:Math.abs(a)*(tt.tol||0.05);ok=Math.abs(x-a)<=tol;msg=ok?'Correcto: '+fm(a,3)+(tt.u?' '+tt.u:'')+'.':'No coincide. Revisa tus medidas y el cálculo'+(tt.pista?': '+tt.pista:'.')}}
   else if(tt.t==='tabla'){ok=S.rows.length>=tt.n;msg=ok?'Tabla completa: '+S.rows.length+' medidas.':'Registra al menos '+tt.n+' medidas (llevas '+S.rows.length+').'}
   else if(tt.t==='meta'){const r=tt.check(S.v,model(),S);ok=!!r.ok;msg=r.msg||(ok?'Logrado.':'Aún no.')}
   S.msg=(ok?'✅ ':'❌ ')+msg;if(ok&&!S.ok[S.ti]){S.ok[S.ti]=1;ctx.act('tarea_ok',{});ctx.obs('Tarea '+(S.ti+1)+' lograda')}tareas()};
  $(el,'#fb_nx').onclick=()=>{S.ti=(S.ti+1)%T.length;S.msg='';tareas()}};
 const lectura=R=>{$(el,'#fb_rd').innerHTML=R?'<b>Lectura de los instrumentos:</b><br>'+OUT.filter(k=>R[k.id]!=null&&!k.oculto).map(k=>esc(k.n)+': <b>'+fmtR(k,R)+'</b> '+esc(k.u||'')).join('<br>'):''};
 if(!cfg.sinMedir)$(el,'#fb_m').onclick=()=>{const o=model();S.n++;const R=read(o);const row={};(cfg.tabla||[]).forEach(c=>{if(S.v[c]!==undefined){const x=VR.find(y=>y.id===c);row[c]=x&&x.tipo==='sel'?((x.opts.find(q=>String(q[0])===String(S.v[c]))||[])[1]||S.v[c]):fm(S.v[c],dec((x&&x.step)||1))}else if(R[c]!=null)row[c]=fmtR(outInfo(c),R)});
  const gv=c=>R[c]!=null?R[c]:S.v[c];if(G){row._gx=G.fx?G.fx(gv(G.x),S.v,R):gv(G.x);row._gy=G.fy?G.fy(gv(G.y),S.v,R):gv(G.y)}S.rows.push(row);S.last=R;lectura(R);tabla();grafica();ctx.act('mide',{});ctx.obs('Medida '+S.rows.length+': '+OUT.filter(k=>R[k.id]!=null&&!k.oculto).map(k=>k.n+' = '+fmtR(k,R)+(k.u?' '+k.u:'')).join(', '))};
 if(!cfg.sinMedir)$(el,'#fb_c').onclick=()=>{S.rows=[];S.last=null;lectura(null);tabla();grafica()};
 let raf=0;const stop=()=>{if(raf)cancelAnimationFrame(raf);raf=0;S.play=0;const b=$(el,'#fb_p');if(b)b.textContent='▶ Simular'};
 if(cfg.anim){$(el,'#fb_p').onclick=()=>{if(raf){stop();return}const a=cfg.anim,x=VR.find(y=>y.id===a.v);S.v[a.v]=x.min;const t0=performance.now();ctx.act('simula',{});$(el,'#fb_p').textContent='⏸ Pausar';const st=n=>{const f=Math.min(1,(n-t0)/(a.dur||4000));S.v[a.v]=x.min+(x.max-x.min)*f;const b=$(el,'#fbv_'+a.v),i=$(el,'#fb_ctl [data-v="'+a.v+'"]');if(b)b.textContent=fm(S.v[a.v],dec(x.step||1));if(i)i.value=S.v[a.v];draw();if(f<1)raf=requestAnimationFrame(st);else stop()};raf=requestAnimationFrame(st)}}
 ctl();tabla();grafica();tareas();draw();U.draw();
 return{pause:stop,reset(){stop();S.rows=[];S.ok={};S.ti=0;S.msg='';S.last=null;S.rd={};VR.forEach(x=>S.v[x.id]=x.v!=null?x.v:(x.tipo==='sel'?x.opts[0][0]:x.min));ctl();lectura(null);tabla();grafica();tareas();draw();U.reset()}}};
return E;})();
